@@
 CREATE TABLE IF NOT EXISTS clearledger.idempotency_keys (
@@
 );
+CREATE OR REPLACE FUNCTION clearledger.accepted(p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
+BEGIN
+ IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR NOT p ?& ARRAY['settlementId','eventId','version','accepted','idempotentReplay'] OR p - ARRAY['settlementId','eventId','version','accepted','idempotentReplay']<>'{}'::jsonb OR p->'accepted' IS DISTINCT FROM 'true'::jsonb OR p->'idempotentReplay' IS DISTINCT FROM 'false'::jsonb OR jsonb_typeof(p->'version') IS DISTINCT FROM 'number' OR (p->>'version') !~ '^[1-9][0-9]*$' OR jsonb_typeof(p->'settlementId') IS DISTINCT FROM 'string' OR jsonb_typeof(p->'eventId') IS DISTINCT FROM 'string' THEN RETURN false; END IF;
+ RETURN (p->>'eventId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND (p->>'settlementId') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
+END $$;
+DO $$ BEGIN
+ IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='clearledger.idempotency_keys'::regclass AND conname='accepted_response_check') THEN
+ ALTER TABLE clearledger.idempotency_keys ADD CONSTRAINT accepted_response_check CHECK(clearledger.accepted(response_body));
+ END IF;
+ IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='clearledger.idempotency_keys'::regclass AND conname='accepted_scope_status_check') THEN
+ ALTER TABLE clearledger.idempotency_keys ADD CONSTRAINT accepted_scope_status_check CHECK (
+  (scope='create:'||(response_body->>'settlementId') AND status_code=201 AND (response_body->>'version')::integer=1) OR
+  (scope='entry:'||(response_body->>'settlementId') AND status_code=202 AND (response_body->>'version')::integer>=2));
+ END IF;
+END $$;
@@
  p := NEW.response_body;
+ IF NOT clearledger.accepted(p) THEN RAISE EXCEPTION 'invalid accepted response' USING ERRCODE='23514'; END IF;
*** End Patch

