arguments.command:
python3 -c 'import sys,json,uuid,time,threading,subprocess,urllib.request,urllib.parse; sys.path.insert(0,"/workspace/submission"); import operations as o; m=o.load(); c=m["auth"]["clients"]["write"]; data=urllib.parse.urlencode(dict(grant_type="client_credentials",client_id=c["client_id"],client_secret=c["client_secret"],scope=c["scope"])).encode(); token=json.load(urllib.request.urlopen(urllib.request.Request(m["auth"]["token_endpoint"],data=data)))["access_token"]; results=[]; errors=[]
def writer():
 for n in range(40):
  sid=str(uuid.uuid4()); body=dict(settlementId=sid,accountId="traffic-account",reference="live-reapply-test",debitParty="Bank-AA",creditParty="Bank-BB",expectedVersion=0); req=urllib.request.Request(m["service_url"]+"/v1/settlements",data=json.dumps(body).encode(),headers={"Authorization":"Bearer "+token,"Content-Type":"application/json","Idempotency-Key":"traffic-"+sid,"X-Correlation-Id":"live-reapply"})
  try:
   with urllib.request.urlopen(req,timeout=30) as r: results.append(r.status)
  except Exception as e: errors.append(str(e))
  time.sleep(0.25)
t=threading.Thread(target=writer); t.start(); result=subprocess.run(["/workspace/submission/deploy.sh"]); t.join(); assert result.returncode==0; assert not errors and results==[201]*40,(errors,results); o.reconcile(); print("PASS re-apply under live traffic: 40 committed writes, no request failures")'

